class Cinema {private boolean booked=false;synchronized boolean book(String name){if(booked){System.out.println(name+" failed: seat unavailable");return false;}booked=true;System.out.println(name+" booked seat");return true;}} public class Main {public static void main(String[]a)throws Exception{Cinema c=new Cinema();Thread x=new Thread(()->c.book("User A"));Thread y=new Thread(()->c.book("User B"));x.start();y.start();x.join();y.join();}}
